import { Box, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React from 'react';
import { useNavigate } from 'react-router-dom';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import RefreshIcon from '@mui/icons-material/Refresh';
import PercentIcon from '@mui/icons-material/Percent';
import NoteAltIcon from '@mui/icons-material/NoteAlt';
import { useAppDispatch, useAppSelector } from '../../../../store/hooks';
import { removeBasket, clearBasket } from '../../store/BasketSlice';
import ConfirmationModel from '../../../../components/ModelPopup/ConfirmationModel';
import PurchaseDiscount from '../PurchaseDiscount';
import BackdropLoading from '../../../../components/BackdropLoading';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const btnLabel = (text: string, color = '#0F1D4D') => (
  <Typography sx={{ fontWeight: 700, fontSize: 11, color, mt: '2px' }}>{text}</Typography>
);

const PurchaseFifthSection = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const [openDiscount, setOpenDiscount] = React.useState(false);
  const [openBackConfirmation, setOpenBackConfirmation] = React.useState(false);
  const [openRefreshConfirmation, setOpenRefreshConfirmation] = React.useState(false);

  const basketItems = useAppSelector((state) => state.purchaseBasket.items);
  const hasItems = basketItems.length > 0;

  const handleBackToDashboard = () => navigate('/dashboard');

  const handleRefresh = () => {
    dispatch(clearBasket());
    setOpenRefreshConfirmation(false);
  };

  const L_TEAL   = 'linear-gradient(135deg, #ccfbf1 0%, #99f6e4 100%)';
  const L_BLUE   = 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)';
  const L_AMBER  = 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)';
  const L_INDIGO = 'linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%)';

  return (
    <Box>
      <Grid container spacing={1}>
        {/* Refresh / Clear */}
        <Grid item key="fifth_refresh" lg={2} sm={4} xs={6}>
          <Item
            onClick={hasItems ? () => setOpenRefreshConfirmation(true) : undefined}
            sx={{ background: L_BLUE, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
          >
            <Stack alignItems="center" direction="column">
              <RefreshIcon sx={{ fontSize: 26, color: '#1d4ed8' }} />
              {btnLabel('Clear', '#1e3a8a')}
            </Stack>
          </Item>
        </Grid>

        {/* Filler */}
        {[1, 2].map((k) => (
          <Grid item key={'fifth_filler_' + k} lg={2} sm={4} sx={{ display: { xs: 'none', lg: 'block' } }} xs={6}>
            <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }} />
          </Grid>
        ))}

        {/* Discount */}
        <Grid item key="fifth_discount" lg={2} sm={4} xs={6}>
          <Item
            onClick={hasItems ? () => setOpenDiscount(true) : undefined}
            sx={{ background: L_AMBER, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
          >
            <Stack alignItems="center" direction="column">
              <PercentIcon sx={{ fontSize: 26, color: '#d97706' }} />
              {btnLabel('Discount', '#92400e')}
            </Stack>
          </Item>
        </Grid>

        {/* Notes */}
        <Grid item key="fifth_notes" lg={2} sm={4} xs={6}>
          <Item sx={{ background: L_INDIGO }}>
            <Stack alignItems="center" direction="column">
              <NoteAltIcon sx={{ fontSize: 26, color: '#4f46e5' }} />
              {btnLabel('Notes', '#312e81')}
            </Stack>
          </Item>
        </Grid>

        {/* Back */}
        <Grid item key="fifth_back" lg={2} sm={4} xs={6}>
          <Item
            onClick={() => hasItems ? setOpenBackConfirmation(true) : handleBackToDashboard()}
            sx={{ background: L_BLUE }}
          >
            <Stack alignItems="center" direction="column">
              <ArrowBackIcon sx={{ fontSize: 26, color: '#1E3A8A' }} />
              {btnLabel('Back')}
            </Stack>
          </Item>
        </Grid>
      </Grid>

      {openDiscount && (
        <PurchaseDiscount
          handleCloseDialog={() => setOpenDiscount(false)}
          openModel={openDiscount}
          title="Add Discount"
        />
      )}

      {openBackConfirmation && (
        <ConfirmationModel
          content="Going back will lose unsaved basket items. Continue?"
          handleClose={() => setOpenBackConfirmation(false)}
          onConfirm={() => handleBackToDashboard()}
          open={openBackConfirmation}
          title="Leave Purchase?"
        />
      )}

      {openRefreshConfirmation && (
        <ConfirmationModel
          content="This will clear all items from the basket. Continue?"
          handleClose={() => setOpenRefreshConfirmation(false)}
          onConfirm={() => handleRefresh()}
          open={openRefreshConfirmation}
          title="Clear Basket?"
        />
      )}
    </Box>
  );
};

export default React.memo(PurchaseFifthSection);
