export interface PurchaseLineCalculation {
  costPerUnit: number;
  discountAmount: number;
  total: number;
  totalQuantity: number;
}

const toNumber = (value: unknown) => {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : 0;
};

export const calculatePurchaseLine = ({
  quantity,
  freeQuantity,
  price,
  discount,
  discountAsPercentage,
}: {
  quantity: unknown;
  freeQuantity: unknown;
  price: unknown;
  discount: unknown;
  discountAsPercentage: boolean;
}): PurchaseLineCalculation => {
  const paidQuantity = Math.max(0, toNumber(quantity));
  const freeQty = Math.max(0, toNumber(freeQuantity));
  const unitPrice = Math.max(0, toNumber(price));
  const discountValue = Math.max(0, toNumber(discount));
  const totalQuantity = paidQuantity + freeQty;
  const grossTotal = paidQuantity * unitPrice;
  const discountAmount = discountAsPercentage
    ? (grossTotal * discountValue) / 100
    : paidQuantity * discountValue;
  const total = Math.max(0, grossTotal - discountAmount);

  return {
    costPerUnit: totalQuantity > 0 ? total / totalQuantity : 0,
    discountAmount: Math.min(grossTotal, discountAmount),
    total,
    totalQuantity,
  };
};

export const filterPurchaseProducts = <
  T extends { code?: string; name?: string },
>(
  products: T[],
  searchValue: string,
) => {
  const query = searchValue.trim().toLocaleLowerCase();
  if (!query) return products;

  return products.filter(
    (product) =>
      product.name?.toLocaleLowerCase().includes(query) ||
      product.code?.toLocaleLowerCase().includes(query),
  );
};
