import { Box, Typography } from '@mui/material';
import React from 'react';
import SupplierSearch from './SupplierSearch';
import { appColors, HEADER_GRADIENT } from '../../../../theme/appColors';
import PurchaseSummary from './Summary';
import PurchaseBasketItems from './BasketItems';
import { BASKET_COLUMNS, BASKET_COMPACT_QUERY } from './basketLayout';

const colHeader = (label: string, align: 'left' | 'right' = 'right') => (
  <Typography
    align={align}
    sx={{
      textTransform: 'uppercase',
      fontWeight: 700,
      fontSize: 10,
      color: 'rgba(255,255,255,0.8)',
      letterSpacing: '0.5px',
      minWidth: 0,
      overflowWrap: 'anywhere',
    }}
  >
    {label}
  </Typography>
);

const PurchaseLeft = () => {
  return (
    <Box
      sx={{
        minWidth: 0,
        minHeight: 0,
        flexShrink: 0,
        height: { xs: 'min(600px, 80dvh)', lg: '100%' },
        display: 'flex',
        flexDirection: 'column',
        zIndex: 10,
        borderRadius: '12px',
        overflow: 'hidden',
        boxShadow: '0 4px 24px rgba(0,20,137,0.14)',
        backgroundColor: appColors.white,
      }}
    >
      {/* Supplier & product search */}
      <Box
        sx={{
          p: '10px 10px 8px 10px',
          backgroundColor: appColors.white,
          borderBottom: `1px solid ${appColors.darkGray[10]}`,
          flexShrink: 0,
        }}
      >
        <SupplierSearch />
      </Box>

      {/* The basket adapts to its panel width and scrolls vertically. */}
      <Box
        sx={{
          flex: 1,
          minHeight: 0,
          minWidth: 0,
          overflowX: 'hidden',
          overflowY: 'auto',
          containerType: 'inline-size',
          containerName: 'purchase-basket',
          backgroundColor: appColors.white,
          scrollbarWidth: 'thin',
          '&::-webkit-scrollbar': { width: '5px' },
          '&::-webkit-scrollbar-thumb': {
            backgroundColor: '#94a3b8',
            borderRadius: '2px',
          },
        }}
      >
        <Box sx={{ minWidth: 0, minHeight: '100%', display: 'flex', flexDirection: 'column' }}>
          <Box
            sx={{
              background: HEADER_GRADIENT,
              display: 'grid',
              gridTemplateColumns: BASKET_COLUMNS,
              gap: 1,
              px: '12px',
              py: '8px',
              position: 'sticky',
              top: 0,
              zIndex: 1,
              [BASKET_COMPACT_QUERY]: { display: 'none' },
            }}
          >
            {colHeader('Item', 'left')}
            {colHeader('Qty / Free')}
            {colHeader('Price')}
            {colHeader('Discount')}
            {colHeader('Amount')}
          </Box>
          <Box sx={{ flex: 1 }}>
            <PurchaseBasketItems />
          </Box>
        </Box>
      </Box>

      {/* Summary footer */}
      <PurchaseSummary />
    </Box>
  );
};

export default React.memo(PurchaseLeft);
