import { Box } from '@mui/material';
import React from 'react';
import PurchaseCategory from './Category';
import PurchaseFourthSection from './FourthSection';
import PurchaseFifthSection from './FifthSection';
import PurchaseLastSection from './LastSection';

const PurchaseRight = () => {
  return (
    <Box
      sx={{
        '--tile-h': { xs: '96px', lg: 'clamp(72px, calc((100dvh - 150px) / 6), 120px)' },
        minWidth: 0,
        minHeight: 0,
        flexShrink: 0,
        overflowY: { xs: 'visible', lg: 'auto' },
        overflowX: { xs: 'visible', lg: 'hidden' },
        display: 'flex',
        flexDirection: 'column',
        gap: '3px',
        pt: 1,
        pl: 1,
        pb: '8px',
      }}
    >
      <Box sx={{ flex: '0 0 auto' }}>
        <PurchaseCategory />
      </Box>
      <Box sx={{ flex: '0 0 auto' }}>
        <PurchaseFourthSection />
      </Box>
      <Box sx={{ flex: '0 0 auto' }}>
        <PurchaseFifthSection />
      </Box>
      <Box sx={{ flex: '0 0 auto' }}>
        <PurchaseLastSection />
      </Box>
    </Box>
  );
};

export default React.memo(PurchaseRight);
