import { Box, Chip, Typography } from '@mui/material';
import React from 'react';
import { appColors } from '../../../../theme/appColors';
import { useSelector } from 'react-redux';
import { selectBasketItems } from '../../store/BasketSelector';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import { BasketItem } from '../../store/BasketSlice';
import AddPurchase from '../AddPurchase';
import { BASKET_COLUMNS, BASKET_COMPACT_QUERY } from './basketLayout';

const profileLabel = (name: string, fontSize?: number) => (
  <Typography
    align="left"
    sx={{
      fontSize: fontSize ?? 13,
      fontWeight: 500,
      color: appColors.royalBlue[100],
      lineHeight: 1.4,
      overflowWrap: 'anywhere',
      [BASKET_COMPACT_QUERY]: { fontWeight: 700 },
    }}
  >
    {name}
  </Typography>
);

const profileValue = (val: string, fontSize?: number) => (
  <Typography
    align="right"
    sx={{
      fontSize: fontSize ?? 13,
      color: appColors.royalBlue[80],
      fontVariantNumeric: 'tabular-nums',
      lineHeight: 1.4,
      overflowWrap: 'anywhere',
      [BASKET_COMPACT_QUERY]: { textAlign: 'left' },
    }}
    title={val}
  >
    {val}
  </Typography>
);

const fieldLabel = (label: string) => (
  <Typography
    sx={{
      display: 'none',
      color: appColors.royalBlue[60],
      fontSize: 10,
      fontWeight: 700,
      mb: 0.5,
      textTransform: 'uppercase',
      [BASKET_COMPACT_QUERY]: { display: 'block' },
    }}
  >
    {label}
  </Typography>
);

const PurchaseBasketItems = () => {
  const selectItem = useSelector(selectBasketItems);
  const [editOpen, setEditOpen] = React.useState(false);
  const [editItem, setEditItem] = React.useState<BasketItem | undefined>();

  if (selectItem.length === 0) {
    return (
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          opacity: 0.35,
          gap: 1,
          py: 4,
        }}
      >
        <Typography sx={{ fontSize: 13, color: appColors.royalBlue[60] }}>
          No items added yet
        </Typography>
      </Box>
    );
  }

  return (
    <Box>
      {selectItem
        .slice()
        .reverse()
        .map((item) => (
          <Box
            key={item.id}
            onClick={() => {
              setEditItem(item);
              setEditOpen(true);
            }}
            sx={{
              display: 'grid',
              gridTemplateColumns: BASKET_COLUMNS,
              alignItems: 'center',
              gap: 1,
              py: '8px',
              px: '12px',
              '& > *': { minWidth: 0 },
              cursor: 'pointer',
              borderBottom: `1px solid ${appColors.darkGray[10]}`,
              '&:last-child': { borderBottom: 'none' },
              borderRadius: '6px',
              transition: 'background 0.15s ease',
              '&:hover': { backgroundColor: appColors.reflexBlue[10] },
              [BASKET_COMPACT_QUERY]: {
                gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
                alignItems: 'start',
                gap: 1.5,
                py: 1.5,
                '& > :first-child': { gridColumn: '1 / -1' },
              },
            }}
          >
            <Box>
              {profileLabel(item.name)}
            </Box>
            <Box>
              {fieldLabel('Qty / Free')}
              <Box
                sx={{
                  alignItems: 'flex-end',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 0.4,
                  [BASKET_COMPACT_QUERY]: { alignItems: 'flex-start' },
                }}
              >
                <Chip
                  label={item.quanity}
                  size="small"
                  sx={{
                    minHeight: 20,
                    height: 'auto',
                    maxWidth: '100%',
                    fontSize: 11,
                    fontWeight: 700,
                    backgroundColor: appColors.reflexBlue[100],
                    color: appColors.white,
                    '& .MuiChip-label': { px: '6px', whiteSpace: 'normal', overflowWrap: 'anywhere' },
                  }}
                />
                {item.freeQty > 0 && (
                  <Chip
                    label={`+${item.freeQty} free`}
                    size="small"
                    sx={{
                      backgroundColor: '#DCFCE7',
                      color: '#166534',
                      fontSize: 9,
                      fontWeight: 700,
                      minHeight: 17,
                      height: 'auto',
                      maxWidth: '100%',
                      '& .MuiChip-label': { px: '5px', whiteSpace: 'normal', overflowWrap: 'anywhere' },
                    }}
                  />
                )}
              </Box>
            </Box>
            <Box>
              {fieldLabel('Price')}
              {profileValue(getPriceFormatWithoutCurrency(item.price ?? 0).toString())}
            </Box>
            <Box>
              {fieldLabel('Discount')}
              {profileValue(
                `${getPriceFormatWithoutCurrency(item.discount ?? 0)}${item.isDiscountPercentage ? '%' : ''}`,
              )}
            </Box>
            <Box>
              {fieldLabel('Amount')}
              {profileValue(
                getPriceFormatWithoutCurrency(
                  item.quanity * (item.price ?? 0),
                ).toString(),
              )}
            </Box>
          </Box>
        ))}
      {editOpen && editItem && (
        <AddPurchase
          handleCloseDialog={() => {
            setEditOpen(false);
            setEditItem(undefined);
          }}
          item={editItem}
          openModel={editOpen}
          title="Edit Purchase Item"
        />
      )}
    </Box>
  );
};

export default React.memo(PurchaseBasketItems);
